// ---------------------------------------------------------------------------
// charge.dispute.closed — lost clawback (S21)
// ---------------------------------------------------------------------------

async function handleDisputeLostClawback(
  dispute: StripeDisputeShape,
  supabase: SupabaseServiceClient,
): Promise<void> {
  const chargeField = dispute.charge
  const chargeId =
    typeof chargeField === 'string'
      ? chargeField
      : ((chargeField as { id?: string } | null)?.id ?? null)

  if (!chargeId) {
    logger.warn({ disputeId: dispute.id }, 'stripe: lost dispute has no charge id — clawback skipped')
    return
  }

  // Step 1: resolve stripe_charges row to get booking_id (and amounts for cross-check)
  const fromCharges = supabase.from.bind(supabase) as unknown as (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        maybeSingle: () => Promise<{
          data: { booking_id: string | null } | null
          error: unknown
        }>
      }
    }
  }

  const { data: chargeRow, error: chargeErr } = await fromCharges('stripe_charges')
    .select('booking_id')
    .eq('charge_id', chargeId)
    .maybeSingle()

  if (chargeErr || !chargeRow) {
    logger.warn(
      { chargeId, disputeId: dispute.id },
      'stripe: lost dispute — stripe_charges row not found, clawback skipped',
    )
    return
  }

  const bookingId = chargeRow.booking_id
  if (!bookingId) {
    logger.warn(
      { chargeId, disputeId: dispute.id },
      'stripe: lost dispute — no booking_id on charge, clawback skipped (no splits to reverse)',
    )
    return
  }

  // Step 2: find all kind='split' commission_splits rows for this booking
  const fromSplits = supabase.from.bind(supabase) as unknown as (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col2: string, val2: string) => {
          returns: <T>() => Promise<{ data: T[] | null; error: unknown }>
        }
      }
    }
  }

  type SplitRow = { id: string; base_amount_cents: number; tip_amount_cents: number }

  const { data: splits, error: splitsErr } = await fromSplits('commission_splits')
    .select('id, base_amount_cents, tip_amount_cents')
    .eq('booking_id', bookingId)
    .eq('kind', 'split')
    .returns<SplitRow>()

  if (splitsErr) {
    logger.error(
      { bookingId, chargeId, disputeId: dispute.id, err: splitsErr },
      'stripe: lost dispute — failed to fetch commission splits, clawback skipped',
    )
    return
  }

  if (!splits || splits.length === 0) {
    logger.info(
      { bookingId, chargeId, disputeId: dispute.id },
      'stripe: lost dispute — no commission splits found for booking, nothing to reverse',
    )
    return
  }

  // Step 3: reverse each split (full amount — dispute lost = full chargeback)
  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpc

  for (const split of splits) {
    const { error: reverseErr } = await rpc(RPC.COMMISSION_SPLIT_REVERSE, {
      p_parent_split_id: split.id,
      p_reverse_amount_cents: split.base_amount_cents,
      p_reverse_tip_cents: split.tip_amount_cents,
      p_reverse_stripe_transfer_id: null,
    })

    if (reverseErr) {
      logger.error(
        { splitId: split.id, chargeId, disputeId: dispute.id, err: reverseErr },
        'stripe: commission_split_reverse failed for lost dispute — clawback not mirrored for this split',
      )
      // Non-fatal per split: continue to next. Reconciliation cron will surface drift.
    } else {
      logger.info(
        { splitId: split.id, bookingId, chargeId, disputeId: dispute.id },
        'stripe: commission split reversed for lost dispute',
      )
    }
  }
}

